mapper.select:
SELECT *
FROM admin_legacy_application_extra_answer
WHERE research_no = #{researchNo}
  AND research_app_seq = #{researchAppSeq}
ORDER BY answer_order ASC, id ASC

SELECT DISTINCT research_app_seq FROM admin_legacy_application_extra_answer WHERE research_app_seq IS NOT NULL AND (
answer_text LIKE CONCAT('%', #{term}, '%') OR raw_answer_text LIKE CONCAT('%', #{term}, '%') OR question_label LIKE CONCAT('%', #{term}, '%')
) ORDER BY research_app_seq DESC LIMIT #{limit}
